<script setup>
import { ref,reactive,onMounted,onUnmounted,computed,watch } from 'vue'
import {api} from './api'
import {maskFromPrefix,prefixFromMask} from './network-address.js'
const props=defineProps({token:String,language:String,idle:Boolean,apiBase:{type:String,default:'/api/admin/network'}})
const emit=defineEmits(['dirty','status'])
const tr=(ru,uz,en)=>({ru,uz,en}[props.language]||ru)
const state=ref(null),error=ref(''),notice=ref(''),busy=ref(false),dirty=ref(false),confirm=ref(false),networks=ref([]),now=ref(Date.now())
watch(state,value=>emit('status',value),{deep:true})
const subnetMask=ref('255.255.255.0')
const newAddress=computed(()=>state.value?.pending?(state.value.interfaces.find(i=>i.interface===state.value.pending.interface)?.address||(form.mode==='static'?form.address:'')):(form.mode==='static'?form.address:state.value?.interfaces.find(i=>i.interface===form.interface)?.address||''))
const connectionUrl=computed(()=>newAddress.value?'http://'+newAddress.value+(props.apiBase.includes('/commissioning/')?'/install':'/admin/connections'):'')
const form=reactive({interface:'eth0',mode:'dhcp',address:'',prefix:24,gateway:'',dns1:'',dns2:'',ssid:'',password:'',security:'wpa-psk'})
const request=(path,options={})=>api(props.apiBase+'/'+path,{token:props.token,...options})
const seconds=computed(()=>Math.max(0,Math.ceil((Number(state.value?.pending?.expires_at || 0)*1000-now.value)/1000)))
function mark(){dirty.value=true;emit('dirty',true);notice.value=''}
function loadInterface(){const data=state.value?.interfaces.find(i=>i.interface===form.interface);if(data){Object.assign(form,data,{dns1:data.dns?.[0]||'',dns2:data.dns?.[1]||'',password:''});subnetMask.value=maskFromPrefix(data.prefix??24)}}
async function refresh(){state.value=await request('status');if(!dirty.value && !state.value.pending)loadInterface()}
async function run(fn){if(busy.value)return;busy.value=true;error.value='';try{await fn()}catch(e){error.value=e.message}finally{busy.value=false}}
async function apply(){if(form.mode==='static'){try{form.prefix=prefixFromMask(subnetMask.value)}catch{throw Error(tr('Укажите корректную маску подсети, например 255.255.255.0.','To‘g‘ri tarmoq niqobini kiriting, masalan 255.255.255.0.','Enter a valid subnet mask, for example 255.255.255.0.'))}}const body={interface:form.interface,mode:form.mode,address:form.address,prefix:form.prefix,gateway:form.gateway,dns:[form.dns1,form.dns2].filter(Boolean),ssid:form.ssid,password:form.password,security:form.security};state.value=await request('apply',{method:'POST',body:JSON.stringify(body)});form.password='';confirm.value=false;dirty.value=false;emit('dirty',false)}
async function settle(action){state.value=await request(action,{method:'POST',body:JSON.stringify({id:state.value.pending.id})});notice.value=action==='confirm'?tr('Сеть сохранена','Tarmoq saqlandi','Network saved'):tr('Прежнее подключение восстановлено','Avvalgi ulanish tiklandi','Previous connection restored');loadInterface()}
let timer;onMounted(()=>{run(refresh);timer=setInterval(()=>{now.value=Date.now();if(state.value?.pending&&!busy.value)run(refresh)},2000)});onUnmounted(()=>clearInterval(timer))
</script>
<template><section class="card content"><h2>{{ tr('Сеть поста','Post tarmog‘i','Station network') }}</h2><p class="muted">{{ tr('Ethernet и Wi-Fi. После применения подтвердите новую связь за 90 секунд, иначе прежняя настройка восстановится.','Ethernet va Wi-Fi. Qo‘llagandan so‘ng 90 soniya ichida yangi ulanishni tasdiqlang, aks holda oldingi sozlama tiklanadi.','Ethernet and Wi-Fi. Confirm the new connection within 90 seconds or the previous configuration will be restored.') }}</p>
<p class="network-help">{{tr('Пост работает с роутером вашей мойки. DHCP получает адрес автоматически. Для постоянного адреса выберите «Статический IP» и укажите параметры сети заказчика.','Post yuvish joyingiz routeri bilan ishlaydi. DHCP manzilni avtomatik oladi. Doimiy manzil uchun «Statik IP»ni tanlang va obyekt tarmog‘i parametrlarini kiriting.','The station uses your site router. DHCP assigns an address automatically. For a fixed address, choose Static IP and enter the customer network settings.')}}</p><div v-if="error" class="message error" role="alert">{{ error }}</div><div v-if="notice" class="message success" role="status">{{ notice }}</div>
<div v-if="state?.pending" class="network-pending"><h3>{{ tr('Проверьте новое подключение','Yangi ulanishni tekshiring','Check the new connection') }} · {{ seconds }} {{ tr('сек','soniya','sec') }}</h3><p>{{ state.pending.interface }}</p><p v-if="newAddress">{{tr('Новый адрес поста','Postning yangi manzili','New station address')}}: <a :href="connectionUrl">{{connectionUrl}}</a></p><p>{{tr('При настройке с компьютера откройте новый адрес в той же локальной сети и подтвердите подключение. При DHCP адрес смотрите на панели или в роутере.','Kompyuterdan sozlashda shu mahalliy tarmoqda yangi manzilni oching va ulanishni tasdiqlang. DHCP manzilini panel yoki routerdan ko‘ring.','From a computer, open the new address on the same LAN and confirm the connection. For DHCP, check the address on the panel or router.')}}</p><div class="actions"><button class="primary" :disabled="busy || seconds<10" @click="run(()=>settle('confirm'))">{{ tr('Связь работает — сохранить','Ulanish ishlayapti — saqlash','Connection works — save') }}</button><button class="quiet" :disabled="busy" @click="run(()=>settle('rollback'))">{{ tr('Вернуть прежнюю сеть','Oldingi tarmoqni qaytarish','Restore previous network') }}</button></div></div>
<div v-if="state" class="table-wrap"><table><thead><tr><th>{{ tr('Интерфейс','Interfeys','Interface') }}</th><th>IPv4</th><th>{{ tr('Шлюз','Shlyuz','Gateway') }}</th><th>{{ tr('Состояние','Holat','Status') }}</th></tr></thead><tbody><tr v-for="i in state.interfaces" :key="i.interface"><th>{{ i.interface }}{{ i.ssid?' · '+i.ssid:'' }}</th><td>{{ i.address?i.address+'/'+i.prefix:'—' }}</td><td>{{ i.gateway || '—' }}</td><td>{{ i.connected?tr('Подключён','Ulangan','Connected'):tr('Нет связи','Ulanmagan','Disconnected') }}{{ i.primary?' · '+tr('Основной','Asosiy','Primary'):'' }}</td></tr></tbody></table></div>
<form v-if="state && !state.pending" @submit.prevent="confirm=true" @input="mark" @change="mark"><div class="fields" style="margin-top:24px"><label>{{ tr('Подключение','Ulanish','Connection') }}<select v-model="form.interface" @change="loadInterface();mark()"><option v-for="i in state.interfaces" :value="i.interface">{{ i.interface==='wlan0'?'Wi-Fi':'Ethernet' }} · {{ i.interface }}</option></select></label><fieldset class="network-mode"><legend>{{tr('IP-адрес поста','Post IP manzili','Station IP address')}}</legend><label><input v-model="form.mode" type="radio" value="dhcp"/>{{tr('Автоматически (DHCP)','Avtomatik (DHCP)','Automatic (DHCP)')}}</label><label><input v-model="form.mode" type="radio" value="static"/>{{tr('Статический IP','Statik IP','Static IP')}}</label></fieldset>
<template v-if="form.interface==='wlan0'"><label>{{ tr('Название Wi-Fi','Wi-Fi nomi','Wi-Fi name') }}<input v-model="form.ssid" required maxlength="32" /></label><label>{{ tr('Пароль Wi-Fi','Wi-Fi paroli','Wi-Fi password') }}<input v-model="form.password" type="password" required minlength="8" maxlength="63" autocomplete="off" /></label><label>{{ tr('Защита','Himoya','Security') }}<select v-model="form.security"><option value="wpa-psk">WPA2 Personal</option><option value="sae">WPA3 Personal</option></select></label><button class="quiet" type="button" :disabled="busy" @click="run(async()=>{networks=(await request('wifi')).networks})">{{ tr('Найти Wi-Fi','Wi-Fi qidirish','Scan Wi-Fi') }}</button><div v-if="networks.length" class="actions full"><button v-for="n in networks" type="button" class="quiet" :disabled="n.security==='unsupported'" @click="form.ssid=n.ssid;form.security=n.security;mark()">{{ n.ssid }} · {{ n.signal }}%</button></div></template>
<template v-if="form.mode==='static'"><p class="full muted">{{tr('У каждого поста должен быть свой свободный IP. Все посты и роутер должны находиться в согласованной подсети. Используйте адрес вне DHCP-пула роутера либо настройте резервирование адресов.','Har bir postning bo‘sh va noyob IP manzili bo‘lsin. Postlar va router mos quyi tarmoqda bo‘lishi kerak. Router DHCP oralig‘idan tashqari manzil yoki manzil band qilishdan foydalaning.','Each station needs a unique unused IP. Stations and router must use compatible subnets. Use an address outside the router DHCP pool or reserve addresses.')}}</p><label>IP<input v-model.trim="form.address" inputmode="decimal" required placeholder="192.168.1.10" /></label><label>{{ tr('Маска подсети','Tarmoq niqobi','Subnet mask') }}<input v-model.trim="subnetMask" inputmode="decimal" placeholder="255.255.255.0" required /></label><label>{{ tr('Шлюз','Shlyuz','Gateway') }}<input v-model.trim="form.gateway" placeholder="192.168.1.1" /></label><label>DNS 1<input v-model.trim="form.dns1" /></label><label>DNS 2<input v-model.trim="form.dns2" /></label></template>
</div><div class="actions" style="margin-top:24px"><button class="primary" :disabled="busy || !dirty || !idle">{{ tr('Применить сеть','Tarmoqni qo‘llash','Apply network') }}</button><button type="button" class="quiet" :disabled="busy || dirty" @click="run(refresh)">{{ tr('Обновить состояние','Holatni yangilash','Refresh status') }}</button></div><p v-if="!idle" class="muted">{{ tr('Изменение сети доступно после завершения текущего сеанса.','Tarmoqni o‘zgartirish joriy seans tugagach mumkin.','Network changes are available after the current wash session is finished.') }}</p></form>
<div v-if="confirm" class="confirm-backdrop"><section class="card confirm-dialog" role="alertdialog" aria-modal="true"><h2>{{ tr('Применить новое подключение?','Yangi ulanishni qo‘llashmi?','Apply the new connection?') }}</h2><p>{{ form.interface }} · {{ form.mode==='static'?form.address+' / '+subnetMask:'DHCP' }} {{ form.ssid }}</p><p>{{ tr('Доступ по прежнему IP может прерваться. Подтвердите связь на панели в течение 90 секунд.','Oldingi IP orqali aloqa uzilishi mumkin. Panelda 90 soniya ichida ulanishni tasdiqlang.','Access through the previous IP may disconnect. Confirm the connection on the panel within 90 seconds.') }}</p><div v-if="error" class="message error" role="alert">{{ error }}</div><div class="actions"><button class="quiet" :disabled="busy" @click="confirm=false">{{ tr('Отмена','Bekor qilish','Cancel') }}</button><button class="primary" :disabled="busy || !idle" @click="run(apply)">{{ tr('Применить','Qo‘llash','Apply') }}</button></div></section></div>
</section></template>

<style scoped>.network-mode{border:1px solid var(--border);padding:16px;border-radius:8px;display:flex;flex-direction:column;gap:16px}.network-mode label{display:flex;flex-direction:row;justify-content:flex-start;text-align:left;align-items:center;gap:12px;min-height:48px;cursor:pointer}.network-mode input{width:24px;height:24px;min-height:24px;margin:0}.network-help{line-height:1.6;margin:20px 0}.network-pending a{overflow-wrap:anywhere}</style>
